CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC');
CREATE TABLE members (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL, role TEXT NOT NULL, PRIMARY KEY(workspace_id,id));
CREATE TABLE accounts (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, industry TEXT NOT NULL, website TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL, employees INTEGER NOT NULL, location TEXT NOT NULL, description TEXT NOT NULL, owner_id TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES members(workspace_id,id));
CREATE TABLE contacts (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, account_id TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, job_title TEXT NOT NULL, phone TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id));
CREATE TABLE opportunities (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, account_id TEXT NOT NULL, contact_id TEXT, name TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), stage TEXT NOT NULL CHECK(stage IN ('Qualified','Discovery','Proposal','Negotiation','Won','Lost')), close_date TEXT NOT NULL, actual_close_date TEXT, owner_id TEXT NOT NULL, last_buyer_activity TEXT NOT NULL, created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id), FOREIGN KEY(workspace_id,contact_id) REFERENCES contacts(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES members(workspace_id,id));
CREATE TABLE activities (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id TEXT, account_id TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, happened_at TEXT NOT NULL, owner_id TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,deal_id) REFERENCES opportunities(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES members(workspace_id,id));
CREATE TABLE tasks (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id TEXT, account_id TEXT NOT NULL, title TEXT NOT NULL, due_date TEXT NOT NULL, owner_id TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0,1)), version INTEGER NOT NULL DEFAULT 1, request_key TEXT, PRIMARY KEY(workspace_id,id), UNIQUE(workspace_id,request_key), FOREIGN KEY(workspace_id,deal_id) REFERENCES opportunities(workspace_id,id), FOREIGN KEY(workspace_id,account_id) REFERENCES accounts(workspace_id,id), FOREIGN KEY(workspace_id,owner_id) REFERENCES members(workspace_id,id));
CREATE TABLE stage_events (id TEXT NOT NULL, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, deal_id TEXT NOT NULL, from_stage TEXT NOT NULL, to_stage TEXT NOT NULL, happened_at TEXT NOT NULL, PRIMARY KEY(workspace_id,id), FOREIGN KEY(workspace_id,deal_id) REFERENCES opportunities(workspace_id,id));
CREATE INDEX opportunities_filter ON opportunities(workspace_id,owner_id,close_date,stage);
CREATE INDEX accounts_search ON accounts(workspace_id,name);
CREATE INDEX contacts_search ON contacts(workspace_id,name);
CREATE INDEX tasks_due ON tasks(workspace_id,completed,due_date);
CREATE INDEX activities_deal ON activities(workspace_id,deal_id,happened_at);
